using System.Globalization;
using System.Resources;

namespace Flagship.Builder;

/// <summary>
/// Text shown to a person, looked up in src/Strings.resx (English) and the satellite
/// assemblies built from src/Strings.&lt;culture&gt;.resx. .NET chooses the satellite from the Windows display
/// language (CurrentUICulture), so there is no language setting in the app. The resx files are generated by
/// scripts/i18n-windows.mjs from i18n/studio-windows; edit those, not the resx.
/// </summary>
internal static class Strings
{
    // The manifest name depends on how the project was built (the app: Flagship.Builder.Strings, the test
    // project may differ), so find the neutral resource by its suffix instead of hard-coding the prefix.
    private static readonly Lazy<ResourceManager?> Manager = new(() =>
    {
        var assembly = typeof(Strings).Assembly;
        var name = assembly.GetManifestResourceNames()
            .FirstOrDefault(n => n.EndsWith(".Strings.resources", StringComparison.Ordinal));
        return name is null ? null : new ResourceManager(name[..^".resources".Length], assembly);
    });

    /// <summary>The text for <paramref name="key"/>; the key itself when the resource is missing.</summary>
    public static string T(string key) => Manager.Value?.GetString(key, CultureInfo.CurrentUICulture) ?? key;

    /// <summary>The text for <paramref name="key"/> with {0}, {1}... filled in using the current culture.</summary>
    public static string F(string key, params object?[] args) => string.Format(CultureInfo.CurrentCulture, T(key), args);
}
